import{z as s,x as n,o as E,c as p,q as r,j as B,D as l,d as t,s as d,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"leveled 对 tiered","description":"","frontmatter":{"title":"leveled 对 tiered","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/leveled-tiered-compaction.md","filePath":"cs/leveled-tiered-compaction.md","lastUpdated":1791413859000}'),A={name:"cs/leveled-tiered-compaction.md"};function c(m,e,D,v,T,L){const i=n("Mermaid");return E(),p("div",null,[e[2]||(e[2]=r('<h1 id="leveled-对-tiered" tabindex="-1">leveled 对 tiered <a class="header-anchor" href="#leveled-对-tiered" aria-label="Permalink to &quot;leveled 对 tiered&quot;">​</a></h1><div class="epigraph"><p>leveled 让每层内部几乎不重叠、容量按倍增；tiered 让同层多个等大文件重叠，归并更懒，写轻读重。</p><footer>—— 据 LevelDB 的 level 设计；Cassandra 对 size-tiered；RocksDB universal；O&#39;Neil LSM</footer></div><p><a href="/cs/lsm-read-amplification">上一课</a>用布隆砍点查 I/O。本课不调假阳性。缺口是 compaction <strong>形状</strong>：同样「多层有序文件」，层内是否允许重叠决定写放大 vs 读放大的主曲线。leveled（分层）与 tiered（分层大小/万能归并族）是两端。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>leveled：第 \\(i\\) 层容量约 \\(T\\) 倍于第 \\(i{-}1\\) 层，层内键范围不重叠（L0 例外）。compaction 把上一层文件与下一层重叠切片归并进去，每字节大约走过每层一次，写放大高，点查每层至多一文件。tiered：同层堆积多个相似大小文件，重叠允许，直到 \\(T\\) 个再整体归并到新层；写放大低，点查同层要看多个文件。</p><p>缺口是选工作负载：写多（指标、消息）偏 tiered；读多点查偏 leveled。混合策略（RocksDB universal 等）是工程插值，本课钉两端。</p><p><span class="marginnote">LevelDB 普及 leveled。Cassandra 早期 size-tiered。写停顿形态不同：leveled 持续小归并，tiered 偶发大归并。空间放大：未回收的旧版本在 tiered 上常更大。</span></p><p><span class="marginnote">「写放大」就是磁盘实际写入量除以业务写入量的比值：业务写 1 GB、盘上重写了 20 GB，写放大就是 20。「读放大」同理是一次点查要翻的文件数。两种 compaction 形状的本质，就是在这两个比值之间做不同的交换。</span></p><p><span class="marginnote">数字实例：取倍率 \\(T=10\\)、L0 上限 100 MB，各层容量就是 100 MB、1 GB、10 GB、100 GB、1 TB——只需 5 层就装下 1 TB 数据。leveled 下点查每层至多翻 1 个文件，约 5-6 次读；tiered 同层可能要看约 \\(T\\) 个文件，读放大肉眼可见地高。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置：层倍率 \\(T\\)、L0 触发文件数、每层压缩器。监控：每层文件数、pending compaction bytes、写停顿次数。换形状等于换放大合同，要伴随容量规划。</p><p>与校准：优化器若把 LSM 表当堆，两种形状的扫描代价都估错；至少应区分「点查期望文件数」。</p>',12)),(E(),B(o,null,{default:l(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LV%5B%22leveled%22%5D%20--%3E%20NO%5B%22%E5%B1%82%E5%86%85%E4%B8%8D%E9%87%8D%E5%8F%A0%22%5D%0A%20%20LV%20--%3E%20WA%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%E9%AB%98%22%5D%0A%20%20LV%20--%3E%20RA%5B%22%E8%AF%BB%E6%94%BE%E5%A4%A7%E4%BD%8E%22%5D%0A%20%20TR%5B%22tiered%22%5D%20--%3E%20OV%5B%22%E5%B1%82%E5%86%85%E9%87%8D%E5%8F%A0%22%5D%0A%20%20TR%20--%3E%20WB%5B%22%E5%86%99%E6%94%BE%E5%A4%A7%E4%BD%8E%22%5D%0A%20%20TR%20--%3E%20RB%5B%22%E8%AF%BB%E6%94%BE%E5%A4%A7%E9%AB%98%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"墓碑回收：leveled 把键推进底层更快，删除空间回收更可预测。tiered 大归并才丢墓碑。快照持有阻碍两者的回收，同 MVCC。",-1)),e[5]||(e[5]=a("p",null,"L0：两种都可能堆积，刷盘快于 compaction 时读放大先在 L0 爆炸——布隆课的最坏情况。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易以为 L0 堆积是 leveled 的毛病。只要刷盘长期快于 compaction 消化，两种形状都会在 L0 堆出一堆重叠文件，点查退化成全翻。所以「L0 文件数」是两种形状都要盯的监控项。")],-1)),(E(),B(o,null,{default:l(()=>[d(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20WT%5B%22%E4%B8%80%E6%AC%A1%E5%86%99%E5%85%A5%22%5D%20--%3E%20MT%5B%22memtable%22%5D%0A%20%20MT%20--%3E%20F0%5B%22%E5%88%B7%E7%9B%98%E6%88%90%20L0%20%E6%96%87%E4%BB%B6%22%5D%0A%20%20F0%20--%3E%20Q%7B%22compaction%20%E5%BD%A2%E7%8A%B6%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22leveled%22%20--%3E%20L1%5B%22%E4%B8%8E%20L1%20%E9%87%8D%E5%8F%A0%E5%8C%BA%E9%97%B4%E5%BD%92%E5%B9%B6%20%E5%B1%82%E5%86%85%E4%BF%9D%E6%8C%81%E4%B8%8D%E9%87%8D%E5%8F%A0%22%5D%0A%20%20Q%20--%20%22tiered%22%20--%3E%20L2%5B%22%E5%90%8C%E5%B1%82%E6%94%92%E6%96%87%E4%BB%B6%20%E7%9B%B4%E5%88%B0%E5%87%91%E6%BB%A1%20T%20%E4%B8%AA%22%5D%0A%20%20L2%20--%3E%20M1%5B%22%E6%95%B4%E4%BD%93%E5%BD%92%E5%B9%B6%E4%B8%80%E6%AC%A1%E6%80%A7%E6%8E%A8%E5%85%A5%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A%20%20L1%20--%3E%20BOT%5B%22%E9%80%90%E5%B1%82%E5%90%91%E4%B8%8B%E6%8E%A8%E8%BF%9B%20%E5%88%B0%E8%BE%BE%E5%BA%95%E5%B1%82%E6%89%8D%E7%9C%9F%E6%AD%A3%E5%9B%9E%E6%94%B6%E5%A2%93%E7%A2%91%22%5D%0A%20%20M1%20--%3E%20BOT%0A"})]),fallback:l(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲列存 PAX。也不把 compaction 当 VACUUM 的同义词——Postgres heap 后课。LSM 形状是文件集合的不变量。</p><p>后课默认：点查多选 leveled；写吞吐选 tiered 或混合。列存与 PAX：分析型页布局，与 LSM 文件内部编码可叠加。</p><p>没有一种形状同时最小写、最小读、最小空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>leveled：层内不重叠，写重读轻；tiered 相反。</li><li>L0 堆积是共同的读放大源头。</li><li>列存与 PAX 下一课：页内把列放在一起服务扫描。</li><li>出处：LevelDB；Cassandra；O&#39;Neil LSM；RocksDB。</li></ul>',6))])}const f=s(A,[["render",c]]);export{h as __pageData,f as default};
